{"command":"cat <<'EOF' > test_reduce.py
import itertools
import random
import json
from problems import Sat, IndependentSet, InvalidInstance
from reduce import reduce


def sat_bruteforce(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    # Edge cases handled naturally
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            # clause satisfied if any literal true
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = bits[var]
                if lit > 0 and val:
                    clause_ok = True
                    break
                if lit < 0 and not val:
                    clause_ok = True
                    break
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False


def indep_set_bruteforce(instance):
    n = instance["n"]
    edges = set()
    for u, v in instance["edges"]:
        edges.add(frozenset((u, v)))
    k = instance["k"]
    # any subset of size >= k that is independent
    for r in range(k, n+1):
        for subset in itertools.combinations(range(n), r):
            good = True
            for u, v in itertools.combinations(subset, 2):
                if frozenset((u, v)) in edges:
                    good = False
                    break
            if good:
                return True
    return False


def random_sat_instance(max_vars=4, max_clauses=4, max_lits=3):
    m = random.randint(0, max_vars)
    num_clauses = random.randint(0, max_clauses)
    clauses = []
    for _ in range(num_clauses):
        lits = []
        for _ in range(random.randint(0, max_lits)):
            if m == 0:
                continue
            var = random.randint(1, m)
            sign = random.choice([1, -1])
            lits.append(sign * var)
        clauses.append(lits)
    return {"num_vars": m, "clauses": clauses}


def run_tests(num_trials=200):
    passed = 0
    for _ in range(num_trials):
        inst = random_sat_instance()
        # validate
        try:
            Sat.validate(inst)
        except InvalidInstance as e:
            print("Invalid generated instance", e)
            continue
        reduced = reduce(inst)
        IndependentSet.validate(reduced)
        sat_ans = sat_bruteforce(inst)
        indep_ans = indep_set_bruteforce(reduced)
        if sat_ans == indep_ans:
            passed += 1
        else:
            print("Mismatch!", json.dumps(inst), json.dumps(reduced), sat_ans, indep_ans)
            return passed, False
    return passed, True

if __name__ == "__main__":
    total, ok = run_tests(500)
    result = {"verified": ok, "tests_run": 500, "tests_passed": total}
    print(json.dumps(result))
    with open("verdict.json", "w") as f:
        json.dump(result, f)
EOF"}

